import torch


def run(inp):
    ref_inp = inp.to(torch.float64)
    return torch.special.scaled_modified_bessel_k1(ref_inp)


def generate_edge_inputs(ctx, device):
    dtype = getattr(torch, ctx["inp__dtype"])
    edge_vals = [
        0.0, 1e-10, 1e-5, 1e-3, 0.1, 1.0, 2.0, 2.1,
        3.0, 5.0, 10.0, 100.0, -0.1, -1.0,
    ]
    inp = torch.tensor(edge_vals, dtype=dtype, device=device)
    return {"inp": inp}


def validate_edge(ref_outputs, sol_outputs, inputs, ctx):
    ref = ref_outputs[0].detach().to("cpu").to(torch.float64)
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    return {
        "passed": bool(
            torch.allclose(sol, ref, rtol=1.3e-6, atol=1e-4, equal_nan=True)
        ),
        "message": "",
        "metrics": {},
    }
